"use strict";
/* ALAN: ders konu haritası, dev hattı (TMAP.dev). Ayrıntı ve ekleme kuralı js/veri/tmap.js başlığında. */
TMAP.dev=[{"k":"DevOps nedir ve kültürü","h":"Neden bazı şirketler günde onlarca kez yayın yaparken bazıları yılda bir kez yapabiliyor?","m":[["DevOps","Geliştirme (Dev) ve operasyon (Ops) ekiplerinin ortak sorumlulukla çalışma kültürü ve pratikleri"],["Otomasyon","Tekrarlanan işleri (derleme, test, dağıtım) elle değil araçla yapmak"],["Geri bildirim döngüsü","Üretimden gelen bilginin (hata, ölçüm) hızla geliştirmeye dönmesi"],["Sürekli iyileştirme","Küçük adımlarla ölç, öğren, düzelt anlayışı"]],"w":"DevOps bir araç değil, çalışma biçimidir. Amaç yazılımı hızlı, güvenli ve tekrarlanabilir şekilde kullanıcıya ulaştırmaktır. Kubernetes gibi araçlar bu kültürün işini kolaylaştırır.","x":"Döngü:\nPlan -> Kodla -> Derle -> Test et -> Yayınla -> Çalıştır -> İzle -> (başa dön)\nKüçük ve sık değişiklik = daha az risk, daha kolay geri alma.","f":[["Ekipler birbirinden kopuk olursa","Geliştirici 'bende çalışıyor' der, operasyon canlıda hata ile uğraşır; yayınlar yavaşlar."],["Her şey elle yapılırsa","Hata ve gecikme artar, aynı işlem iki kez aynı sonucu vermez."]],"u":[["DevOps'un asıl amacı nedir?","Yazılımı ortak sorumlulukla hızlı ve güvenilir teslim etmek","Operasyon ekibini kapatıp işi geliştiricilere yıkmak","Yılda bir kez büyük sürüm çıkarmak"],["Küçük ve sık yayın neden tercih edilir?","Hata riski ve geri alma maliyeti düşer","Test gereksinimi tamamen ortadan kalkar","Sunucu sayısı otomatik azalır"],["Hangisi DevOps kültürüne en uygundur?","Üretim hatasından öğrenip süreci iyileştirmek","Hatalı kişiyi bulup cezalandırmak","Yayın sürecini tek kişide tutmak"]],"p":["DevOps'un amacını anlatacaksın","Geliştirme-operasyon döngüsünü sayacaksın","Otomasyonun neden gerekli olduğunu açıklayacaksın"],"o":"Sonunda DevOps döngüsünün aşamalarını sayıp her aşamanın neden var olduğunu söyleyebileceksin.","c":{"a":"Eski yaklaşım","b":"DevOps yaklaşımı","r":[["Yayın sıklığı","Ayda veya yılda bir","Günde birçok kez"],["Sorumluluk","Ekipler arasında atılır","Ortak üstlenilir"],["Dağıtım","Elle ve riskli","Otomatik ve tekrarlanabilir"]]},"n":["DevOps nedir ve kültürü"]},{"k":"Linux ve komut satırı","h":"Sunucuda fare yok, sadece siyah ekran var. Nereden başlarsın?","m":[["Kabuk (shell)","Komutları alıp işletim sistemine ileten program; en yaygını bash"],["İzinler","Dosya için sahip, grup, diğerleri ve r (4), w (2), x (1) hakları"],["Süreç (process)","Çalışan program örneği; ps ve top ile izlenir"],["systemd","Servisleri başlatan ve yöneten sistem; systemctl ile kullanılır"]],"w":"Sunucuların büyük çoğunluğu Linux çalıştırır, konteynerler de Linux çekirdeğine dayanır. Komut satırını bilmeden DevOps araçlarını anlamak zordur.","x":"pwd\nls -l /var/log\ncd /var/log && tail -n 20 syslog\ngrep -i error /var/log/syslog | tail -n 5\nchmod 640 rapor.txt     (sahip: oku+yaz, grup: oku, diğerleri: yok)\nps aux | grep nginx\nsystemctl status nginx\njournalctl -u nginx -f\ndf -h     (disk doluluğu)\nss -tulpn     (dinlenen portlar)\nDikkat: rm -rf komutu geri dönüşsüz siler, yolu iki kez kontrol et.","f":[["Dosya izinleri çok açık olursa (chmod 777)","Her kullanıcı dosyayı değiştirebilir; güvenlik açığı doğar."],["Disk dolarsa","Servisler yazamaz, log ve veritabanı durur; uygulama çöker."]],"u":[["Bir dizinin içeriğini uzun biçimde listeleyen komut hangisidir?","ls -l","pwd -l","cd -l"],["chmod 640 dosya izni ne anlama gelir?","Sahip okur ve yazar, grup okur, diğerleri erişemez","Sahip yalnız okur, herkes yazabilir","Herkes okur ve yazar"],["Bir servisin durumunu systemd ile hangi komut gösterir?","systemctl status nginx","ps status nginx","journalctl restart nginx"]],"p":["Dizinde gezinip dosya okuyacaksın","İzin sayılarını çözeceksin","Servis durumunu ve logları kontrol edeceksin"],"o":"Sonunda bir Linux sunucuda servis durumunu, portları, diski ve logları komutla kontrol edebileceksin.","n":["Linux ve komut satırı"]},{"k":"Bash betikleme","h":"Her sabah aynı beş komutu elle yazmaktan nasıl kurtulursun?","m":[["Shebang","Betiğin ilk satırı; hangi yorumlayıcıyla çalışacağını söyler"],["Değişken","Değeri saklayan ad; kullanımı $AD biçimindedir"],["Çıkış kodu","Komut bitince verdiği sayı; 0 başarı, diğerleri hata; $? ile okunur"],["Boru (pipe)","Bir komutun çıktısını sonrakine girdi yapar (|)"]],"w":"Betik, tekrarlayan işi güvenilir hale getirir. CI/CD ve konteyner komutlarının çoğu kısa Bash betikleriyle bağlanır.","x":"#!/usr/bin/env bash\nset -euo pipefail     # hata olursa dur, tanımsız değişken kullanma\nKAYNAK=\"$HOME/proje\"\nHEDEF=\"/tmp/yedek-$(date +%F).tar.gz\"\nif [ ! -d \"$KAYNAK\" ]; then\n  echo \"Dizin yok: $KAYNAK\" >&2\n  exit 1\nfi\ntar -czf \"$HEDEF\" \"$KAYNAK\"\necho \"Yedek hazır: $HEDEF\"\nÇalıştırmak için: chmod +x yedek.sh && ./yedek.sh","f":[["set -e kullanılmazsa","Ortadaki komut hata verse de betik devam eder, sonuç yanlış ama başarılı görünür."],["Değişkenler tırnaksız yazılırsa","Boşluklu dosya adları bölünür; yanlış dosyalar silinebilir veya işlenir."]],"u":[["Betiğin ilk satırındaki #!/usr/bin/env bash ne işe yarar?","Betiği hangi yorumlayıcının çalıştıracağını belirtir","Betiği otomatik olarak şifreler","Betiğe çalıştırma izni verir"],["Önceki komutun başarılı olup olmadığını hangi değer gösterir?","$? değeri 0 ise başarılıdır","$? değeri 1 ise başarılıdır","$# değeri 0 ise başarılıdır"],["Betikte bir hata olunca durmasını hangi ayar sağlar?","set -e","set -x","set -v"]],"p":["Basit bir betik yazacaksın","Çıkış kodlarını yorumlayacaksın","Güvenli betik alışkanlıkları edineceksin"],"o":"Sonunda hata olunca duran, parametre alan küçük bir yedekleme betiği yazabileceksin.","n":["Bash betikleme"]},{"k":"Git ve takım akışı","h":"Beş kişi aynı dosyayı değiştirirse kim kazanır?","m":[["Commit","Değişikliklerin açıklamalı anlık görüntüsü"],["Dal (branch)","Ana hattan ayrılıp izole çalışma yapılan çizgi"],["Pull request","Dalın ana dala birleştirilmeden önce gözden geçirilmesi isteği"],["Trunk-based","Herkesin küçük değişiklikleri sık sık ana dala birleştirdiği akış"]],"w":"Takım halinde güvenli çalışmak için kodun geçmişi, gözden geçirme ve geri alma gerekir. CI/CD ve GitOps bu akışın üstüne kurulur.","x":"git clone https://github.com/ornek/uygulama.git\ncd uygulama\ngit switch -c ozellik/giris-sayfasi\ngit add .\ngit commit -m 'Giriş sayfası eklendi'\ngit push -u origin ozellik/giris-sayfasi\n(GitHub'da Pull Request aç, gözden geçirme sonrası main'e birleştir)\ngit pull --rebase origin main     (ana daldaki yenilikleri al)\ngit log --oneline --graph -10","f":[["Doğrudan main'e kontrolsüz push yapılırsa","Hatalı kod gözden geçirilmeden yayına kadar gider."],["Dallar haftalarca ayrı yaşarsa","Birleştirirken büyük çakışmalar (merge conflict) çıkar."]],"u":[["Git'te yeni bir dal açıp ona geçmek için hangi komut kullanılır?","git switch -c yeni-dal","git branch -d yeni-dal","git merge yeni-dal"],["Pull request'in temel amacı nedir?","Değişikliği birleştirmeden önce incelemek ve CI ile doğrulamak","Depoyu bilgisayara kopyalamak","Commit geçmişini silmek"],["Kısa ömürlü dallar ve sık birleştirme hangi akışın özelliğidir?","Trunk-based development","Uzun vadeli sürüm dalları","Dallanmayı tamamen yasaklama"]],"p":["Dal açıp commit atacaksın","PR akışını anlatacaksın","Çakışma riskini azaltan alışkanlıkları sayacaksın"],"o":"Sonunda dal açıp değişiklik yapıp pull request ile ana dala birleştirebileceksin.","c":{"a":"GitHub flow / trunk-based","b":"Gitflow","r":[["Dal sayısı","Az: main ve kısa ömürlü dallar","Çok: develop, release, hotfix"],["Yayın sıklığı","Sık, sürekli teslimata uygun","Planlı sürümlere uygun"],["Karmaşıklık","Düşük","Yüksek"]]},"n":["Git ve takım akışı"]},{"k":"Ağ, DNS ve HTTP","h":"Tarayıcıya adres yazdığında arka planda hangi adımlar işler?","m":[["DNS","Alan adını IP adresine çeviren sistem; A kaydı IPv4, AAAA kaydı IPv6 verir"],["Port","Bir IP'de hangi servise gidileceğini söyleyen numara: HTTP 80, HTTPS 443, SSH 22"],["HTTP durum kodu","200 başarılı, 301 yönlendirme, 404 bulunamadı, 500 sunucu hatası, 502/503 arka uç sorunu"],["Yük dengeleyici","Gelen isteği birden çok sunucuya dağıtan bileşen"]],"w":"Uygulamaya erişilemediğinde sorunun DNS'te mi, ağda mı, uygulamada mı olduğunu ayırt etmek DevOps'un günlük işidir. Kubernetes Service ve Ingress de bu temele dayanır.","x":"dig example.com +short          (alan adı hangi IP'ye çözülüyor)\ncurl -I https://example.com      (yalnız başlıkları ve durum kodunu göster)\nping -c 3 example.com\nss -tulpn | grep :80             (bu sunucuda 80 dinleniyor mu)\nIP ile açılıyor ama alan adıyla açılmıyorsa sorun büyük ihtimalle DNS'tedir.","f":[["DNS kaydı yanlışsa","Alan adı yanlış sunucuya gider veya hiç çözülmez; site açılmaz."],["Güvenlik duvarı portu kapatırsa","Servis çalışsa bile dışarıdan bağlantı zaman aşımına uğrar."]],"u":[["DNS A kaydı neyi eşler?","Alan adını IPv4 adresine","Alan adını posta sunucusuna","IP adresini MAC adresine"],["HTTPS için varsayılan port hangisidir?","443","80","22"],["Bir uygulama 502 Bad Gateway dönüyorsa en olası sebep nedir?","Önündeki proxy arka uç uygulamadan geçerli yanıt alamıyor","Tarayıcı çerezleri dolmuş","DNS A kaydı IPv6 tipinde"]],"p":["DNS çözümlemesini anlatacaksın","Yaygın port ve durum kodlarını bileceksin","dig ve curl ile ilk teşhisi yapacaksın"],"o":"Sonunda 'site açılmıyor' şikayetinde DNS, port ve HTTP düzeyinde ilk teşhisi yapabileceksin.","n":["Ağ, DNS ve HTTP"]},{"k":"CI/CD ve GitHub Actions","h":"Kodu her kaydettiğinde testlerin kendiliğinden çalışmasını ister misin?","m":[["CI (sürekli entegrasyon)","Değişikliklerin sık birleştirilip her seferinde otomatik derlenmesi ve test edilmesi"],["CD (sürekli teslimat/dağıtım)","Doğrulanmış sürümün hazır tutulması veya otomatik yayına alınması"],["Pipeline","Derle, test et, paketle, dağıt aşamalarının otomatik zinciri"],["Artifact","Pipeline'ın ürettiği paket veya imaj; bir kez üretilir, her ortama aynı gider"]],"w":"Elle yayın hataya açıktır. Pipeline her değişikliği aynı kurallarla denetler ve hatayı erken yakalar.","x":"Dosya: .github/workflows/ci.yml\nname: ci\non:\n  push:\n    branches: [main]\n  pull_request:\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Testleri çalıştır\n        run: ./test.sh\n      - name: Gizli bilgi kullanımı\n        run: echo \"Anahtar gizli: ${{ secrets.API_KEY != '' }}\"\nGizli değerler Settings > Secrets bölümünden girilir, YAML'a yazılmaz.","f":[["Testler pipeline'a konmazsa","Hatalı kod fark edilmeden yayına çıkar."],["Gizli bilgi YAML'a düz yazılırsa","Depoya erişen herkes anahtarı görür; anahtar sızmış sayılır."]],"u":[["CI'ın temel işi nedir?","Her değişikliği otomatik derleyip test etmek","Sunucuları fiziksel olarak kurmak","Canlı trafiği izlemek"],["GitHub Actions iş akışı dosyaları nerede tutulur?",".github/workflows/ dizininde","/etc/actions/ dizininde","docs/ci/ dizininde"],["Test aşaması başarısız olduğunda pipeline ne yapmalıdır?","Sonraki dağıtım aşamalarını durdurmalıdır","Dağıtıma yine de devam etmelidir","Testi sessizce atlamalıdır"]],"p":["CI ve CD farkını anlatacaksın","Basit bir workflow dosyası okuyacaksın","Gizli bilgiyi güvenli kullanacaksın"],"o":"Sonunda her push'ta testleri çalıştıran bir GitHub Actions workflow'u yazabileceksin.","c":{"a":"Sürekli teslimat","b":"Sürekli dağıtım","r":[["Üretime çıkış","Onay veya düğme ile","Otomatik, insan müdahalesiz"],["Risk yönetimi","Son kontrol insanda","Test kalitesine tam güven gerekir"],["Hazır sürüm","Her zaman hazır","Her zaman hazır ve yayında"]]},"n":["CI/CD ve GitHub Actions"]},{"k":"Konteyner, imaj ve registry","h":"'Bende çalışıyor' sorununu nasıl çözersin?","m":[["Konteyner","Uygulamayı bağımlılıklarıyla yalıtılmış çalıştıran süreç; host çekirdeğini paylaşır"],["İmaj (image)","Konteynerin salt okunur şablonu; katmanlardan oluşur"],["Registry","İmajların saklandığı ve çekildiği depo (Docker Hub, ECR, GHCR)"],["OCI","Open Container Initiative: imaj ve çalışma zamanı için açık standartlar"]],"w":"Konteyner, uygulamanın her ortamda aynı çalışmasını sağlar. Kubernetes konteynerleri yönetir; önce konteyneri anlamak gerekir.","x":"docker pull nginx:1.27\ndocker run -d --name web -p 8080:80 nginx:1.27     (host 8080 -> konteyner 80)\ndocker ps\ndocker logs web\ndocker exec -it web sh\ndocker stop web && docker rm web\ndocker images\ndocker image prune     (kullanılmayan imajları temizler, disk açar)\nKonteyner ile VM farkı: konteyner çekirdeği paylaşır, VM kendi çekirdeğini çalıştırır.","f":[["Etiket olarak sürekli latest kullanılırsa","Hangi sürümün çalıştığı belirsizleşir, geri dönüş ve tekrar üretim zorlaşır."],["Konteyner silinirse ve veri içeride tutulduysa","Konteynerin yazılabilir katmanındaki veri kaybolur."]],"u":[["Konteyner ile sanal makine arasındaki temel fark nedir?","Konteyner host işletim sistemi çekirdeğini paylaşır","Konteyner kendi çekirdeğini çalıştırır","Konteyner yalnız Windows'ta çalışır"],["docker run -p 8080:80 ifadesi ne yapar?","Host'un 8080 portunu konteynerin 80 portuna yönlendirir","Konteynerin 8080 portunu host'un 80 portuna yönlendirir","Her iki portu da kapatır"],["İmajların saklandığı ve paylaşıldığı yere ne ad verilir?","Registry","Namespace","Runtime"]],"p":["Konteyner ve VM farkını anlatacaksın","Temel docker komutlarını kullanacaksın","Registry ve OCI kavramlarını bileceksin"],"o":"Sonunda bir imajı çekip konteyner olarak çalıştırıp logunu okuyabileceksin.","c":{"a":"Konteyner","b":"Sanal makine","r":[["Çekirdek","Host ile paylaşılır","Kendi çekirdeği vardır"],["Açılış süresi","Saniyeler","Dakikalar"],["Yalıtım","Süreç düzeyinde","Donanım düzeyinde (daha güçlü)"]]},"n":["Konteyner, imaj ve registry"]},{"k":"Dockerfile, volume, ağ ve Compose","h":"Uygulamanı ve veritabanını tek komutla ayağa kaldırabilir misin?","m":[["Dockerfile","İmajın nasıl üretileceğini adım adım anlatan metin dosyası"],["Volume","Konteyner silinse bile kalan kalıcı veri alanı"],["Docker ağı","Konteynerlerin birbirini ad ile bulduğu sanal ağ (varsayılan sürücü bridge)"],["Docker Compose","Birden çok servisi tek YAML dosyasıyla tanımlayıp yöneten araç"]],"w":"Gerçek uygulamalar tek konteynerden oluşmaz. Dockerfile ile paket üretilir, volume ile veri korunur, Compose ile yerel ortam kolayca kurulur.","x":"Dockerfile:\nFROM python:3.12-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\nUSER 1000\nCMD [\"python\", \"app.py\"]\n\ncompose.yaml:\nservices:\n  web:\n    build: .\n    ports: ['8080:8000']\n    depends_on: [db]\n  db:\n    image: postgres:16\n    environment:\n      POSTGRES_PASSWORD_FILE: /run/secrets/dbpass\n    secrets: [dbpass]\n    volumes: ['dbdata:/var/lib/postgresql/data']\nsecrets:\n  dbpass:\n    file: ./dbpass.txt      (Git'e koyma; .gitignore'a ekle)\nvolumes:\n  dbdata:\n\ndocker build -t uygulama:1.0 .\ndocker compose up -d\ndocker compose logs -f web\ndocker compose down        (volume kalır)\ndocker compose down -v     (DİKKAT: volume ve veritabanı verisi de silinir)","f":[["Bağımlılık dosyası kodla birlikte en başta kopyalanırsa","Her kod değişikliğinde bağımlılıklar yeniden kurulur; derleme yavaşlar."],["Veritabanı için volume tanımlanmazsa","Konteyner yeniden oluşturulunca veriler kaybolur."]],"u":[["Konteyner silinse bile verinin kalması için ne kullanılır?","Volume","Ek bir CMD satırı","Daha büyük bir imaj"],["Compose'ta web servisi veritabanına nasıl ulaşır?","Servis adıyla, aynı Compose ağı üzerinden","Yalnızca host IP adresiyle","Doğrudan imaj adıyla"],["Dockerfile'da neden önce bağımlılık dosyası kopyalanır?","Katman önbelleğinden yararlanıp derlemeyi hızlandırmak için","Kod gizli kalsın diye","Konteyner root olsun diye"]],"p":["Basit bir Dockerfile yazacaksın","Volume ve ağ mantığını açıklayacaksın","Compose ile iki servisi ayağa kaldıracaksın"],"o":"Sonunda web ve veritabanından oluşan bir uygulamayı Compose ile yerelde çalıştırabileceksin.","n":["Dockerfile, volume, ağ ve Compose"]},{"k":"Kubernetes mimarisi","h":"Yüzlerce konteyner varsa hangisi hangi sunucuda çalışacak, kim karar verir?","m":[["Control plane","Kümeyi yöneten katman: kube-apiserver, etcd, kube-scheduler, kube-controller-manager"],["Node (düğüm)","Pod'ların çalıştığı makine; kubelet, kube-proxy ve container runtime içerir"],["etcd","Küme durumunu saklayan dağıtık anahtar-değer veritabanı"],["CRI / CNI / CSI","Çalışma zamanı, ağ ve depolama için standart arayüzler"]],"w":"Kubernetes (K8s), konteynerleri otomatik yerleştirir, ölçekler ve onarır. Mimariyi bilmek hata ayıklamanın ve KCNA'nın en ağırlıklı alanının temelidir.","x":"Kullanıcı -> kubectl -> kube-apiserver -> etcd (durum)\nkube-scheduler: Pod'u uygun düğüme atar\nkubelet (düğümde): Pod'u çalıştırır, durumu bildirir\ncontainerd: konteyneri fiilen başlatır (CRI üzerinden)\n\nYerel lab (ücretsiz): kind create cluster   veya   minikube start\nkubectl cluster-info\nkubectl get nodes\nkubectl api-resources     (kümedeki nesne türleri)","f":[["etcd kaybolur ve yedek yoksa","Küme durumu gider; hangi iş yüklerinin olduğu bilinmez."],["kubelet bir düğümde durursa","O düğümdeki Pod'lar yönetilemez, düğüm NotReady olur."]],"u":[["Pod'u uygun bir düğüme atayan bileşen hangisidir?","kube-scheduler","kubelet","etcd"],["Küme durumunu hangi bileşen saklar?","etcd","kube-proxy","containerd"],["Düğümde Pod'ları çalıştırıp durumlarını API sunucusuna bildiren ajan hangisidir?","kubelet","kube-controller-manager","kubectl"]],"p":["Control plane bileşenlerini sayacaksın","Düğüm bileşenlerini ayıracaksın","kubectl ile küme durumuna bakacaksın"],"o":"Sonunda bir isteğin kubectl'den düğümdeki konteynere nasıl ulaştığını adım adım anlatabileceksin.","c":{"a":"Control plane","b":"Worker node","r":[["Görev","Kararları verir, durumu tutar","Uygulama Pod'larını çalıştırır"],["Bileşen","API server, etcd, scheduler","kubelet, kube-proxy, runtime"],["Kaybı","Yönetim durur, çalışanlar sürebilir","O düğümdeki Pod'lar etkilenir"]]},"n":["Kubernetes mimarisi"]},{"k":"Pod, Deployment ve ölçekleme","h":"Bir Pod çökerse kim yenisini başlatır, yeni sürümü kesintisiz nasıl yayarsın?","m":[["Pod","Kubernetes'in en küçük birimi; bir veya birkaç konteyner, ortak ağ ve depolama"],["Deployment","İstenen Pod sayısını ve sürümünü tanımlar; ReplicaSet üzerinden yönetir"],["Rolling update","Eski Pod'ları kademeli kapatıp yenilerini açarak kesintisiz güncelleme"],["Probe","Liveness: canlı mı, yeniden başlat; readiness: trafik almaya hazır mı"]],"w":"Pod'lar geçicidir. Deployment 'istenen durum' ile 'gerçek durum' farkını kapatır; ölçekleme ve güncelleme böylece tek komutla yapılır.","x":"kubectl create deployment web --image=nginx:1.27 --replicas=2\nkubectl get deploy,pods\nkubectl scale deployment web --replicas=4\nkubectl set image deployment/web nginx=nginx:1.27.1\nkubectl rollout status deployment/web\nkubectl rollout undo deployment/web     (önceki sürüme dön)\nkubectl describe pod POD_ADI\nkubectl logs POD_ADI\nVarsayılan rolling update ayarı: maxSurge %25, maxUnavailable %25.\nOtomatik ölçekleme: HPA Pod sayısını, Cluster Autoscaler düğüm sayısını ayarlar.","f":[["Readiness probe tanımlanmazsa","Hazır olmayan Pod trafik alır, kullanıcı hata görür."],["Kaynak istekleri (requests) düğüm kapasitesini aşarsa","Pod Pending durumunda kalır, hiçbir düğüme yerleşmez."]],"u":[["Deployment neyi garanti eder?","İstenen sayıda Pod'un çalışmasını ve kontrollü güncellemeyi","Pod'ların hep aynı düğümde kalmasını","Pod verisinin kalıcı olmasını"],["Hatalı yeni sürümü hızlıca geri almak için hangi komut kullanılır?","kubectl rollout undo deployment/web","kubectl delete node web","kubectl scale --undo web"],["Pod'a trafik gitmesini hangi probe belirler?","Readiness probe","Liveness probe","Startup log"]],"p":["Pod ve Deployment farkını anlatacaksın","Ölçekleme ve güncelleme komutlarını kullanacaksın","Probe türlerini ayıracaksın"],"o":"Sonunda bir Deployment oluşturup ölçekleyebilir, güncelleyebilir ve geri alabileceksin.","n":["Pod, Deployment ve ölçekleme"]},{"k":"Service, Ingress ve ağ","h":"Pod'ların IP'si sürekli değişiyorsa uygulamaya nasıl sabit adresle ulaşırsın?","m":[["Service","Etiketle seçilen Pod'lara sabit sanal IP ve DNS adı veren erişim noktası"],["Service türleri","ClusterIP (küme içi), NodePort (30000-32767 arası), LoadBalancer (bulut yük dengeleyici)"],["Ingress / Gateway API","HTTP(S) isteklerini alan adına ve yola göre Service'lere yönlendiren kurallar"],["NetworkPolicy","Hangi Pod'un hangisiyle konuşabileceğini sınırlayan kural"]],"w":"Pod'lar gelip gider; Service ağ erişimini kararlı kılar. Ingress ve NetworkPolicy ise dış erişimi ve iç güvenliği yönetir.","x":"kubectl expose deployment web --port=80 --type=ClusterIP\nkubectl get svc\nkubectl get endpoints web     (Service hangi Pod IP'lerine bakıyor)\nkubectl port-forward svc/web 8080:80     (yerelde test)\nKüme içi DNS adı: web.default.svc.cluster.local\nDikkat: LoadBalancer türü bulutta saatlik ücretli yük dengeleyici açar; işin bitince sil: kubectl delete svc web\nIngress için ayrıca bir ingress denetleyicisi gerekir. Gateway API daha yeni nesil standarttır.","f":[["Service selector'ı Pod etiketleriyle eşleşmezse","Endpoints boş kalır, trafik hiçbir Pod'a gitmez."],["NetworkPolicy hiç yoksa","Varsayılan olarak tüm Pod'lar birbirine erişebilir; saldırı yayılımı kolaylaşır."]],"u":[["ClusterIP türü Service'e nereden erişilir?","Yalnızca küme içinden","İnternetten doğrudan","Yalnızca tek bir düğümden"],["Service'in hangi Pod'lara trafik göndereceğini ne belirler?","Label selector","Pod adının uzunluğu","Namespace rengi"],["Alan adına ve URL yoluna göre HTTP yönlendirmesi için hangi nesne kullanılır?","Ingress","ConfigMap","PersistentVolume"]],"p":["Service türlerini ayıracaksın","Endpoints ile bağlantıyı doğrulayacaksın","Ingress ve NetworkPolicy amacını anlatacaksın"],"o":"Sonunda bir Deployment'ı Service ile yayınlayıp erişimi test edebileceksin.","c":{"a":"ClusterIP","b":"LoadBalancer","r":[["Erişim","Küme içi","Dışarıdan"],["Maliyet","Yok","Bulutta ücretli yük dengeleyici"],["Kullanım","Servisler arası iletişim","İnternete açılan servis"]]},"n":["Service, Ingress ve ağ"]},{"k":"ConfigMap, Secret, namespace ve depolama","h":"Aynı imajı hem test hem canlıda farklı ayarlarla nasıl çalıştırırsın?","m":[["ConfigMap","Gizli olmayan yapılandırma verisi; ortam değişkeni veya dosya olarak verilir"],["Secret","Parola ve anahtar gibi hassas veri; varsayılan olarak yalnızca base64 kodludur, şifreli değildir"],["Namespace","Kümeyi mantıksal bölümlere ayırır; isim ve kota yalıtımı sağlar"],["PersistentVolume / PVC","Kalıcı depolama alanı ve Pod'un bu alanı talep etmesi"]],"w":"Yapılandırma imajdan ayrılmalıdır. Böylece aynı imaj her ortamda çalışır, hassas veriler ayrı korunur ve ekipler birbirini etkilemez.","x":"kubectl config current-context     (önce hangi kümede olduğunu doğrula; denemeyi yalnız yerel kümede yap: kind/minikube)\nkubectl create namespace test\nkubectl create configmap uygulama-ayar --from-literal=LOG_SEVIYE=debug -n test\nkubectl create secret generic db-parola --from-literal=parola='GucluBirParola' -n test\nkubectl get secret db-parola -n test -o yaml     (değer base64'tür, çözmek kolaydır)\nkubectl get pods -n test\nkubectl config set-context --current --namespace=test\npvc.yaml:\napiVersion: v1\nkind: PersistentVolumeClaim\nmetadata:\n  name: veri-pvc\n  namespace: test\nspec:\n  accessModes: ['ReadWriteOnce']\n  resources:\n    requests:\n      storage: 1Gi\nkubectl apply -f pvc.yaml\nkubectl get pvc -n test\nkubectl delete namespace test     (içindeki her şeyi siler; PVC de gider)\nSecret'ları etcd'de şifrelemek ve RBAC ile kısıtlamak gerekir.","f":[["Secret düz YAML olarak depoya konursa","Base64 şifreleme değildir; depoya erişen herkes değeri çözer."],["PVC olmadan veritabanı Pod'u çalıştırılırsa","Pod yeniden oluşunca veriler kaybolur."]],"u":[["Secret nesnesindeki base64 kodlama neyi ifade eder?","Şifreleme değil, yalnızca kodlamadır","Askeri düzeyde şifrelemedir","Sıkıştırmadır"],["Aynı kümede dev ve prod iş yüklerini mantıksal ayırmak için ne kullanılır?","Namespace","Service","Probe"],["Pod yeniden başlasa da veri kalmalıysa hangi nesne gerekir?","PersistentVolumeClaim","ConfigMap","ReplicaSet"]],"p":["ConfigMap ve Secret farkını anlatacaksın","Namespace ile ortamları ayıracaksın","Kalıcı depolama mantığını kavrayacaksın"],"o":"Sonunda yapılandırma ve hassas veriyi imajdan ayırıp Pod'a güvenli şekilde verebileceksin.","c":{"a":"ConfigMap","b":"Secret","r":[["İçerik","Gizli olmayan ayarlar","Parola, token, anahtar"],["Saklama","Düz metin","base64 (şifreli değil, ek önlem gerekir)"],["Erişim","Standart","RBAC ve şifreleme ile kısıtlanmalı"]]},"n":["ConfigMap, Secret, namespace ve depolama"]},{"k":"Helm ve GitOps","h":"Kümedeki durum ile depodaki dosyalar farklılaşırsa ne olmalı?","m":[["Helm","Kubernetes için paket yöneticisi; uygulama paketine chart denir"],["values.yaml","Chart'ın ayarlarını ortama göre değiştirmeye yarayan değer dosyası"],["GitOps","İstenen durumun Git'te tutulup kümeye otomatik uygulandığı yöntem"],["Argo CD / Flux","Git'i izleyip kümeyi ona eşitleyen GitOps araçları (CNCF)"]],"w":"Elle kubectl apply ile yönetilen küme zamanla dağılır. Helm paketlemeyi, GitOps denetlenebilir ve geri alınabilir teslimatı sağlar.","x":"helm repo add bitnami https://charts.bitnami.com/bitnami\nhelm repo update\nhelm install demo bitnami/nginx --set replicaCount=2\nhelm list\nhelm upgrade demo bitnami/nginx --set replicaCount=3\nhelm rollback demo 1\nhelm uninstall demo     (kaynakları siler)\nhelm template demo bitnami/nginx     (kuruluma gerek kalmadan YAML üret)\nGitOps ilkeleri (OpenGitOps): bildirimsel, sürümlü ve değişmez, otomatik çekilen, sürekli uzlaştırılan.","f":[["Kümeye elle müdahale edilirse (GitOps varken)","Araç farkı görür ve değişikliği Git'teki hale geri çeker (drift düzeltme)."],["Chart sürümü sabitlenmezse","Aynı komut farklı zamanda farklı sürüm kurabilir."]],"u":[["GitOps'ta gerçeğin tek kaynağı nedir?","Git deposu","Çalışan kümenin elle yapılan ayarları","Geliştiricinin bilgisayarı"],["Helm chart nedir?","Kubernetes kaynaklarını paketleyen şablonlu uygulama paketi","Bir izleme panosu","Bir ağ eklentisi"],["Argo CD veya Flux ne yapar?","Git'teki istenen durumu kümeye sürekli uygular ve uzlaştırır","Konteyner imajı derler","Logları toplar"]],"p":["Helm ile uygulama kurup geri alacaksın","GitOps ilkelerini sayacaksın","Pull tabanlı dağıtımın faydasını anlatacaksın"],"o":"Sonunda bir Helm chart kurup yükseltebilir ve GitOps'un neden güvenli olduğunu anlatabileceksin.","c":{"a":"CI'dan kubectl ile itme (push)","b":"GitOps (çekme, pull)","r":[["Kimlik bilgisi","Kümeye erişim CI'da tutulur","Ajan küme içinden Git'i okur"],["Sapma","Fark edilmez","Otomatik düzeltilir"],["Geri alma","Elle","Git revert ile"]]},"n":["Helm ve GitOps"]},{"k":"Kod olarak altyapı: Terraform ve Ansible","h":"Aynı sunucu ortamını elle iki kez kurup birebir aynı yapabilir misin?","m":[["IaC","Altyapıyı elle değil, sürüm kontrollü kodla tanımlama ve oluşturma"],["Terraform plan/apply","plan neyin değişeceğini gösterir, apply uygular"],["State","Terraform'un yönettiği gerçek kaynakların kaydı; gizli veri içerebilir"],["Ansible","Ajansız (SSH ile) yapılandırma aracı; playbook'lar idempotenttir"]],"w":"Altyapıyı kodlamak tekrar üretilebilirlik ve denetim sağlar. Terraform kaynağı oluşturur, Ansible sunucunun içini yapılandırır.","x":"main.tf (bulut maliyeti olmayan lab örneği):\nterraform {\n  required_providers {\n    local = { source = \"hashicorp/local\" }\n  }\n}\nresource \"local_file\" \"selam\" {\n  content  = \"Merhaba DevOps\"\n  filename = \"${path.module}/selam.txt\"\n}\n\nterraform init\nterraform fmt\nterraform validate\nterraform plan\nterraform apply\nterraform destroy     (oluşturulan kaynakları siler)\n\nAnsible:\nansible all -i envanter.ini -m ping\nansible-playbook -i envanter.ini site.yml --check     (kuru çalıştırma)\nBulut kaynağıyla çalışırken: apply öncesi plan'ı oku, işin bitince destroy et, aksi halde ücret yazar.","f":[["State dosyası kaybolursa","Terraform mevcut kaynakları tanımaz; tekrar oluşturmaya çalışır veya sahipsiz kaynak kalır."],["plan okunmadan apply edilirse","Beklenmeyen silme veya yeniden oluşturma yaşanabilir, veri kaybolur."]],"u":[["terraform plan ne yapar?","Değişiklikleri uygulamadan önce gösterir","Kaynakları siler","State dosyasını şifreler"],["Takımda Terraform state'i neden uzak (remote) backend'de tutulur?","Ortak erişim ve kilitleme ile çakışmayı önlemek için","Kod daha hızlı derlensin diye","Provider kurulmasın diye"],["Ansible'da idempotent ne demektir?","Aynı playbook tekrar çalışınca gereksiz değişiklik yapmaz","Playbook yalnız bir kez çalışır","Her çalışmada tüm sunucuyu sıfırlar"]],"p":["IaC mantığını anlatacaksın","Terraform temel akışını uygulayacaksın","Ansible'ın rolünü ayıracaksın"],"o":"Sonunda bir Terraform projesini init, plan, apply ve destroy ile yönetebileceksin.","c":{"a":"Terraform","b":"Ansible","r":[["Ana iş","Altyapı kaynağı oluşturma","Sunucu içi yapılandırma"],["Yaklaşım","Bildirimsel, state tutar","Görev tabanlı, ajansız SSH"],["Örnek","Ağ, sanal makine, depolama","Paket kur, dosya yaz, servis başlat"]]},"n":["Kod olarak altyapı: Terraform ve Ansible"]},{"k":"Gözlemlenebilirlik ve günlükleme","h":"Kullanıcı 'yavaş' dediğinde sorunun hangi serviste olduğunu nasıl bulursun?","m":[["Metrik, log, trace","Sayısal ölçümler, olay kayıtları ve isteğin servisler arası izi"],["Prometheus","Hedeflerden metrik çeken (pull), PromQL ile sorgulanan zaman serisi veritabanı"],["Grafana","Prometheus gibi kaynaklardan grafik panosu ve alarm kuran araç"],["Alertmanager","Prometheus alarmlarını gruplayıp e-posta veya sohbet gibi kanallara yollar"]],"w":"Gözlemlenebilirlik, sistemin içinde ne olduğunu dışarıdan sorarak anlamayı sağlar. İzlenmeyen sistem arızada kör uçuş demektir.","x":"Varsayılan portlar: Prometheus 9090, Alertmanager 9093, Grafana 3000, node_exporter 9100.\nPromQL örnekleri:\nrate(http_requests_total[5m])     (saniyedeki istek oranı)\nhistogram_quantile(0.95, sum(rate(http_request_duration_seconds_bucket[5m])) by (le))     (p95 gecikme)\nLog toplama: Fluent Bit / Fluentd -> Loki veya Elasticsearch\nTrace standardı: OpenTelemetry; görüntüleme: Jaeger\nkubectl logs POD_ADI --previous     (çöken konteynerin önceki logu)\nİyi alarm: kullanıcıyı etkileyen belirtiye (hata oranı, gecikme) bağlanır.","f":[["Her küçük dalgalanmada alarm kurulursa","Alarm yorgunluğu oluşur; gerçek alarm gözden kaçar."],["Loglar yalnızca konteynerin içinde tutulursa","Pod silinince loglar da gider; arıza sonrası inceleme yapılamaz."]],"u":[["Prometheus metrikleri nasıl toplar?","Hedeflerin /metrics adresinden periyodik çeker (pull)","Hedefler her saniye ona e-posta atar","Yalnızca log dosyalarını okur"],["Gözlemlenebilirliğin üç temel sinyali hangileridir?","Metrik, log, trace","CPU, RAM, disk","Commit, merge, deploy"],["Grafana ile Prometheus arasındaki ilişki nedir?","Prometheus veriyi toplar, Grafana görselleştirir","Grafana veriyi çeker, Prometheus çizer","İkisi aynı işi yapar"]],"p":["Üç sinyali ayıracaksın","Prometheus ve Grafana rollerini anlatacaksın","Log toplamanın neden merkezi olması gerektiğini açıklayacaksın"],"o":"Sonunda bir servis için hangi metrik, log ve alarmın gerekli olduğunu söyleyebileceksin.","c":{"a":"Metrik","b":"Log","r":[["Biçim","Sayısal, zaman serisi","Metin olay kaydı"],["Soru","Ne kadar? Ne sıklıkla?","Tam olarak ne oldu?"],["Maliyet","Düşük","Hacimli, daha pahalı"]]},"n":["Gözlemlenebilirlik ve günlükleme"]},{"k":"Gizli bilgi yönetimi ve DevSecOps","h":"Bir geliştirici yanlışlıkla API anahtarını GitHub'a yükledi. Şimdi ne yapılır?","m":[["Gizli bilgi yönetimi","Anahtarları kodda değil Vault, AWS Secrets Manager gibi kasada tutmak"],["En az yetki","Her kullanıcıya ve hesaba yalnızca işi için gereken izin (Kubernetes'te RBAC)"],["İmaj taraması","İmajdaki bilinen zafiyetleri (CVE) pipeline'da yakalamak; örnek araç Trivy"],["Pod güvenliği","Root olmayan çalışma, salt okunur dosya sistemi, Pod Security Standards (privileged, baseline, restricted)"]],"w":"Güvenliği sona bırakmak pahalıdır. DevSecOps güvenlik denetimlerini pipeline'ın içine alır; hata erken ve ucuza yakalanır.","x":"trivy image nginx:1.27     (imajdaki zafiyetleri listeler)\nkubectl auth can-i delete pods -n test --as=system:serviceaccount:test:ci\nkubectl create role pod-okuyucu --verb=get,list --resource=pods -n test\nkubectl create rolebinding pod-okuyucu-bag --role=pod-okuyucu --serviceaccount=test:ci -n test\nSızan anahtar: önce iptal et ve yenile, sonra geçmişten temizle. Silmek yetmez, git geçmişinde kalır.\nDockerfile: USER ile root olmayan kullanıcıya geç; imaj küçük ve güncel tut.\nYalnız kendi sistemlerinde ve izinli ortamda tarama yap.","f":[["Anahtar kod deposunda kalırsa","Depoya erişen veya geçmişi tarayan herkes anahtarı kullanabilir."],["Her hesaba cluster-admin verilirse","Tek bir ele geçirilen hesap tüm kümeyi ele geçirir."]],"u":[["Sızan bir anahtar için ilk adım nedir?","Anahtarı iptal edip yenisini üretmek","Dosyayı sessizce silmek","Depoyu yeniden adlandırmak"],["En az yetki ilkesi ne der?","Her kimliğe yalnızca gerekli izinler verilir","Herkes yönetici olur","İzinler yılda bir artırılır"],["Pipeline'daki imaj taraması neyi amaçlar?","Bilinen zafiyetli imajları yayından önce yakalamak","Kodu daha hızlı derlemek","İmajı küçültmek"]],"p":["Gizli bilginin yerini bileceksin","RBAC ve en az yetkiyi uygulayacaksın","İmaj taramasını pipeline'a yerleştireceksin"],"o":"Sonunda bir pipeline ve kümeye eklenecek temel güvenlik denetimlerini sayabileceksin.","n":["Gizli bilgi yönetimi ve DevSecOps"]},{"k":"Bulutta DevOps: AWS eşlemesi","h":"Pipeline, imaj deposu, çalıştırma ve izleme için AWS'de hangi servisler var?","m":[["CodePipeline / CodeBuild","AWS'nin pipeline ve derleme/test servisleri (GitHub Actions'ın karşılığı)"],["ECR / ECS / EKS","Imaj deposu, AWS'nin konteyner çalıştırıcısı ve yönetilen Kubernetes"],["CloudWatch","Metrik, log ve alarm servisi (Prometheus ve Grafana'nın bir karşılığı)"],["IAM","Kimlik ve izin yönetimi; en az yetki burada uygulanır"]],"w":"Bulut, altyapıyı dakikalar içinde kurdurur ama kullandığın kadar ücret yazar. Kavramlar aynıdır; yalnız servis adları değişir.","x":"aws sts get-caller-identity     (hangi hesapla işlem yaptığını doğrula)\naws ecr create-repository --repository-name uygulama\naws ecr get-login-password | docker login --username AWS --password-stdin HESAP_ID.dkr.ecr.BOLGE.amazonaws.com\ndocker push HESAP_ID.dkr.ecr.BOLGE.amazonaws.com/uygulama:1.0\naws logs tail /ecs/uygulama --follow\nMALİYET UYARISI: EKS kontrol düzlemi, NAT Gateway, yük dengeleyici ve Fargate çalışırken saatlik ücret yazar. Lab bitince kaynakları sil (terraform destroy veya konsoldan), bütçe alarmı kur.","f":[["Kaynaklar lab sonrası silinmezse","Beklenmedik fatura gelir; NAT Gateway ve yük dengeleyici sessizce ücret yazar."],["Uzun ömürlü kök anahtar CI'da kullanılırsa","Sızarsa tüm hesap risk altında olur; rol tabanlı geçici kimlik tercih edilmeli."]],"u":[["AWS'de konteyner imajlarını saklamak için hangi servis kullanılır?","ECR","CloudWatch","CodeBuild"],["Sunucu yönetmeden konteyner çalıştırmak isteyen takım ne seçer?","ECS üzerinde Fargate","Elle kurulmuş VM","Yalnızca S3"],["AWS'de metrik, log ve alarm hangi serviste toplanır?","CloudWatch","IAM","Route 53"]],"p":["AWS DevOps servislerini eşleyeceksin","Maliyet riskli kaynakları tanıyacaksın","Geçici kimlik mantığını anlatacaksın"],"o":"Sonunda bir pipeline'ı AWS servisleriyle eşleştirip silme ve maliyet adımını planlayabileceksin.","c":{"a":"Genel araç","b":"AWS karşılığı","r":[["Pipeline","GitHub Actions","CodePipeline + CodeBuild"],["İmaj deposu","Docker Hub","ECR"],["İzleme","Prometheus + Grafana","CloudWatch"]]},"n":["Bulutta DevOps: AWS eşlemesi"]},{"k":"SRE temelleri","h":"'Sistem yüzde yüz çalışsın' hedefi neden yanlış bir hedeftir?","m":[["SLI","Ölçülen güvenilirlik göstergesi, örneğin başarılı istek oranı"],["SLO","SLI için hedef değer, örneğin aylık %99,9 başarı"],["Hata bütçesi","100 eksi SLO; izin verilen hata payı. Tükenirse yeni yayınlar yavaşlar"],["Postmortem","Olay sonrası suçlayıcı olmayan inceleme ve iyileştirme listesi"]],"w":"Mükemmel güvenilirlik çok pahalıdır ve yeniliği durdurur. SRE (Site Reliability Engineering), güvenilirlik ile hız arasında ölçülü denge kurar.","x":"SLO %99,9 (30 günlük ay): hata bütçesi = 0,1%\n30 gün = 43.200 dakika -> yaklaşık 43 dakika kesinti hakkı\nOlay müdahalesi: tespit -> sınıflandır -> görevlendir (olay komutanı) -> azalt (önce kullanıcıyı koru, gerekirse geri al) -> iletişim -> çöz -> postmortem\nÖlçütler: MTTD (tespit süresi), MTTR (onarım süresi)\nPostmortem sorusu: 'Kim hata yaptı?' değil, 'Sistem bu hatayı neden mümkün kıldı?'","f":[["SLO tanımlanmazsa","Ne kadar güvenilirliğin yeterli olduğu belirsiz kalır; ekipler tartışır."],["Postmortem suçlama odaklı olursa","İnsanlar hatayı saklar, kök neden bulunamaz, olay tekrar eder."]],"u":[["Hata bütçesi nasıl hesaplanır?","100 eksi SLO yüzdesi","SLO ile SLA'nın toplamı","MTTR bölü MTTD"],["Aylık %99,9 SLO yaklaşık kaç dakika kesinti payı bırakır (30 gün)?","Yaklaşık 43 dakika","Yaklaşık 4 saat","Yaklaşık 7 dakika"],["Olay sırasında önceliğin ilk adımı nedir?","Kullanıcı etkisini azaltmak (gerekirse geri alma)","Kök nedeni kesin kanıtlamak","Raporu yazmak"]],"p":["SLI, SLO ve SLA farkını anlatacaksın","Hata bütçesini hesaplayacaksın","Postmortem kültürünü açıklayacaksın"],"o":"Sonunda bir servis için SLO belirleyip hata bütçesini dakika olarak hesaplayabileceksin.","c":{"a":"SLO","b":"SLA","r":[["Kimin için","Ekip içi hedef","Müşteriyle yapılan sözleşme"],["Aşılırsa","Yayınlar yavaşlar, odak değişir","Ceza veya iade doğabilir"],["Sıkılık","Genellikle daha sıkı","Genellikle daha gevşek"]]},"n":["SRE temelleri"]},{"k":"Kubernetes iş yükü türleri ve zamanlama","h":"Veritabanı, her düğümde çalışacak log toplayıcı ve gece çalışan bir yedek işi aynı Deployment ile mi yönetilir?","m":[["StatefulSet","Kalıcı kimlik (db-0, db-1) ve kendi diskini koruyan Pod'lar; veritabanı gibi durum tutan iş yükleri için"],["DaemonSet","Her düğümde (ya da seçilen düğümlerde) birer Pod çalıştırır; log ve izleme ajanları için"],["Job / CronJob","Job bir işi başarıyla bitene kadar çalıştırır; CronJob aynı işi takvime bağlar"],["Zamanlama kuralları","requests yerleşim için ayrılan miktar, limits üst sınır; taint düğümü iter, toleration geçiş izni verir; nodeSelector ve affinity Pod'u düğüme çeker"]],"w":"Her iş yükü Deployment'a uymaz: durum tutmak, düğüm başına çalışmak ve işi bitirip kapanmak ayrı denetleyiciler ister. Scheduler ise Pod'u kaynak isteklerine ve kurallara göre bir düğüme yerleştirir; yerleştiremezse Pod Pending kalır.","x":"Yerel kümede dene (kind/minikube). Önce: kubectl config current-context\njob.yaml:\napiVersion: batch/v1\nkind: Job\nmetadata:\n  name: selam\nspec:\n  template:\n    spec:\n      restartPolicy: Never\n      containers:\n      - name: selam\n        image: busybox:1.36\n        command: [\"sh\", \"-c\", \"echo merhaba; date\"]\nkubectl apply -f job.yaml\nkubectl get jobs\nkubectl logs job/selam\nkubectl delete job selam\nkubectl create cronjob dakika --image=busybox:1.36 --schedule=\"* * * * *\" -- date\nkubectl get cronjob,jobs\nkubectl delete cronjob dakika\nkubectl get daemonset -n kube-system     (kube-proxy gibi bileşenler her düğümde birer Pod)\nKaynak isteği (container altında): resources: { requests: { cpu: 100m, memory: 128Mi }, limits: { memory: 256Mi } }\nTaint (yalnız kendi yerel düğümünde): kubectl taint nodes DUGUM_ADI ozel=gpu:NoSchedule     (geri almak için sonuna - ekle)\nPending Pod nedeni: kubectl describe pod POD_ADI     (Events bölümü)","f":[["Durum tutan veritabanını Deployment ile çalıştırırsan","Pod yeniden oluşunca kimliği ve diski karışabilir; StatefulSet ve kalıcı depolama gerekir."],["Taint'li düğüme toleration vermeden Pod göndermeye çalışırsan","Pod Pending kalır; describe olaylarında taint nedeni yazar."]],"u":[["Her düğümde birer ajan Pod'u çalıştırmak için hangi nesne kullanılır?","DaemonSet","Deployment","Job"],["Bir kez çalışıp başarıyla tamamlanması gereken iş için hangi nesne uygundur?","Job","DaemonSet","Service"],["Taint'li bir düğüme Pod'un yerleşebilmesi için ne gerekir?","Eşleşen bir toleration","Daha fazla replika","Daha büyük imaj"],["Pod'a düğümde ayrılacak asgari CPU ve bellek miktarını hangi alan belirler?","requests","limits","labels"]],"p":["Deployment, StatefulSet, DaemonSet ve Job türlerini ayıracaksın","requests ve limits farkını anlatacaksın","Pending bir Pod'un zamanlama nedenini olaylardan okuyacaksın"],"o":"Sonunda verilen bir iş yükü için doğru denetleyici türünü seçebilecek ve bir Pod'un neden düğüme yerleşmediğini olaylardan okuyabileceksin.","n":["Kubernetes iş yükü türleri ve zamanlama"]},{"k":"Dağıtım stratejileri ve Kubernetes'te sorun giderme","h":"Yeni sürüm yayında Pod'lar CrashLoopBackOff'a düştü. Önce neye bakarsın, riski baştan nasıl küçültürdün?","m":[["Rolling ve Recreate","Rolling Pod'ları kademeli değiştirir (kesinti yok, iki sürüm bir süre birlikte çalışır); Recreate önce hepsini kapatır (kesinti olur, sürüm karışmaz)"],["Blue/green","İki tam ortam yan yana durur; trafik tek anahtarla yeniye çevrilir, geri dönüş de aynı hızdadır; kaynak iki katı gerekir"],["Canary","Yeni sürüm önce küçük bir trafik payı alır; metrikler iyiyse pay artar, kötüyse geri çekilir"],["Pod hata durumları","ImagePullBackOff imaj çekilemiyor, CrashLoopBackOff konteyner sürekli çöküyor, Pending yerleşemiyor; nedeni describe olayları ve loglar söyler"]],"w":"Her yayın risk taşır. Strateji, hatanın kaç kullanıcıya ulaşacağını sınırlar; sorun giderme ise Pod durumundan nedene giden sabit bir sıra izler: durum, olaylar, log. Tahmin yürütmek yerine sırayı izlersin.","x":"Teşhis sırası (yerel kümede):\nkubectl get pods                          (STATUS: ImagePullBackOff, CrashLoopBackOff, Pending)\nkubectl describe pod POD_ADI              (en alttaki Events bölümü nedeni söyler)\nkubectl logs POD_ADI --previous           (çöken konteynerin önceki logu)\nkubectl get events --sort-by=.lastTimestamp\nkubectl debug -it POD_ADI --image=busybox:1.36 --target=KONTEYNER_ADI     (çalışan Pod'a geçici hata ayıklama konteyneri)\n\nBozuk yayın alıştırması (yalnız yerel kümede):\nkubectl create deployment bozuk --image=nginx:9.99.99     (olmayan etiket)\nkubectl get pods -l app=bozuk             (ImagePullBackOff)\nkubectl describe pod -l app=bozuk         (Events: imaj bulunamadı)\nkubectl set image deployment/bozuk nginx=nginx:1.27\nkubectl rollout status deployment/bozuk\nkubectl delete deployment bozuk\n\nCanary taslağı: Service seçicisi yalnız app: web. Kararlı Deployment 9 replika (etiket surum: kararli), canary Deployment 1 replika (surum: canary); iki Pod türü de app: web taşır, trafiğin kabaca onda biri canary'ye gider. Tam oran kontrolü için Gateway API ağırlıkları ya da service mesh gerekir.\nBlue/green taslağı: web-mavi ve web-yesil Deployment'ları; Service seçicisini surum: yesil'e çevirmek geçişi tek adımda yapar, geri dönüş seçiciyi eski değere almaktır.","f":[["Readiness probe olmadan canary'ye trafik verirsen","Hazır olmayan Pod istek alır; canary bozuksa kullanıcı daha metriğe bakmadan etkilenir."],["Yalnız kubectl get pods bakıp bırakırsan","Neden Events ve loglardadır; describe ve logs --previous olmadan tahmin yürütürsün."]],"u":[["Hatalı yeni sürümü önce küçük bir kullanıcı payına açan strateji hangisidir?","Canary","Recreate","Blue/green"],["Geri dönüşü tek bir anahtar çevirmeyle sağlayan, iki tam ortam isteyen strateji hangisidir?","Blue/green","Rolling update","Canary"],["ImagePullBackOff durumunda en olası neden nedir?","İmaj adı ya da etiketi yanlış, yahut registry erişimi yok","Readiness probe geç kalıyor","Service seçicisi eksik"],["Çöken konteynerin bir önceki çalışmadaki logunu hangi komut gösterir?","kubectl logs POD_ADI --previous","kubectl get logs --old","kubectl describe log POD_ADI"]],"p":["Rolling, blue/green ve canary stratejilerini karşılaştıracaksın","Pod durumundan olaylara ve loga giden teşhis sırasını uygulayacaksın","Bozuk bir Deployment'ı bulup düzelteceksin"],"o":"Sonunda bozuk bir yeni sürümü describe, olaylar ve loglarla teşhis edip düzeltebilecek ve riske göre bir yayın stratejisi seçebileceksin.","n":["Dağıtım stratejileri ve Kubernetes'te sorun giderme"]},{"k":"Bulut yerel mimari ve CNCF ekosistemi","h":"Mikroservis, sunucusuz ve service mesh: hangisi ne zaman gerekir, hepsini kim standartlaştırıyor?","m":[["Bulut yerel yaklaşım","Küçük bağımsız servisler (mikroservis), konteynerde çalışan, bildirimsel API ve otomasyonla yönetilen, ölçeklenebilir ve dayanıklı sistemler"],["Otomatik ölçekleme","HPA Pod sayısını, VPA Pod kaynak isteğini, Cluster Autoscaler düğüm sayısını, KEDA olay kaynağına göre Pod sayısını ayarlar"],["Sunucusuz ve service mesh","Sunucusuz: kullanıldıkça çalışan, boştayken sıfıra inen iş yükü (ör. Knative). Service mesh: servisler arası trafik, mTLS ve gözlem uygulama koduna dokunmadan yönetilir (ör. Istio, Linkerd)"],["CNCF ve açık standartlar","CNCF projeleri sandbox, incubating, graduated olgunluk basamaklarından geçer; OCI, CRI, CNI, CSI arayüzleri satıcıya bağımlılığı azaltır"]],"w":"Bulut yerel bir araç listesi değil bir tasarım yaklaşımıdır: servisleri küçük tut, işi otomasyona bırak, standart arayüzlerle tek satıcıya bağlanma. KCNA bu ekosistemin haritasını sorar; her aracın ayrıntısını değil, hangi sorunu çözdüğünü bil.","x":"Yığın (aşağıdan yukarıya):\naltyapı -> konteyner çalışma zamanı (OCI imajı, CRI) -> Kubernetes -> ağ (CNI) + depolama (CSI) -> service mesh -> uygulama\n\nSorun -> araç sınıfı:\nYük artınca Pod sayısı: HPA     |  Pod'un kaynak isteği: VPA     |  Düğüm sayısı: Cluster Autoscaler     |  Olay kuyruğuna göre: KEDA\nServisler arası şifreli trafik ve yeniden deneme: service mesh (sidecar ya da sidecar'sız)\nBoştayken sıfıra inen iş yükü: Knative gibi sunucusuz katman\nMetrik, log, iz: Prometheus, OpenTelemetry (gözlemlenebilirlik konusuna bak)\n\nHPA'yı yerelde dene (Pod'da cpu requests tanımlı olmalı; minikube: minikube addons enable metrics-server):\nkubectl autoscale deployment web --cpu-percent=50 --min=2 --max=5\nkubectl get hpa\nkubectl delete hpa web\nmetrics-server yoksa TARGETS sütunu <unknown> görünür; bu beklenen davranıştır.\nService mesh kısmı simülasyondur: kurmadan, bir istekte sidecar'ın araya girişini kâğıda çiz.","f":[["Her sorunu service mesh ile çözmeye çalışırsan","Karmaşıklık ve kaynak maliyeti artar; küçük sistemde gereksizdir."],["Mikroservisi yalnız daha küçük kod sanırsan","Ağ gecikmesi, dağıtık hata ve gözlem ihtiyacı doğar; sınırları iş alanına göre çiz."]],"u":[["Pod sayısını CPU kullanımına göre otomatik ayarlayan nesne hangisidir?","HorizontalPodAutoscaler (HPA)","Ingress","ConfigMap"],["Servisler arası mTLS ve trafik yönetimini uygulama koduna dokunmadan sağlayan katman nedir?","Service mesh","Registry","Namespace"],["CNCF olgunluk basamaklarından en olgun olanı hangisidir?","Graduated","Sandbox","Incubating"],["Konteyner imajı ve çalışma zamanı için açık standartları hangi girişim yayımlar?","OCI","CNI","CSI"]],"p":["Bulut yerel yaklaşımı ve mikroservis dengesini anlatacaksın","Ölçekleme, sunucusuz ve service mesh araçlarını çözdükleri sorunla eşleyeceksin","CNCF olgunluk basamaklarını ve OCI, CRI, CNI, CSI standartlarını ayıracaksın"],"o":"Sonunda verilen bir ihtiyaç için doğru bulut yerel araç sınıfını (ölçekleme, mesh, sunucusuz, gözlem) seçebilecek ve CNCF olgunluk basamaklarını açıklayabileceksin.","n":["Bulut yerel mimari ve CNCF ekosistemi"]},{"k":"Terraform ileri: değişken, modül, durum ve HCP Terraform","h":"Aynı Terraform kodunu dev ve prod için nasıl kullanır, state dosyasını takımla güvenle nasıl paylaşırsın?","m":[["Değişken, çıktı, doğrulama","variable girdi, output çıktı; validation ve precondition yanlış girdiyi plan aşamasında yakalar; sensitive çıktıyı gizler ama state'e yine yazar"],["count, for_each, lifecycle","count ve for_each kaynağı çoğaltır; bağımlılık çoğunlukla referanstan çıkar, depends_on yalnız örtük bağ yoksa gerekir; create_before_destroy ve prevent_destroy yaşam döngüsünü ayarlar"],["Modül","Yeniden kullanılabilir kaynak grubu; girdisi variable, çıktısı output ile açılır, kaynağı yerel yol ya da registry olur, version ile sabitlenir"],["Uzak durum, kilit, drift","backend state'i ortak yerde saklar, kilit eşzamanlı apply'ı engeller; drift gerçek altyapı ile state farkıdır; import mevcut kaynağı yönetime alır, state list/show durumu inceler"],["HCP Terraform","Terraform'u uzakta çalıştıran, state'i ve kilidi tutan, workspace ve proje ile ekipleri düzenleyen yönetilen hizmet"]],"w":"Küçük bir proje tek dosyaya sığar; takım ve çok ortam başlayınca değişkenler, modüller ve ortak state gerekir. En pahalı Terraform hataları state yanlış yönetilince çıkar.","x":"Yerel alıştırma (bulut yok; local sağlayıcı). Dosyalar:\nmodules/not/main.tf\nvariable \"dosya_adi\" { type = string }\nvariable \"icerik\" {\n  type    = string\n  default = \"merhaba\"\n  validation {\n    condition     = length(var.icerik) > 0\n    error_message = \"icerik boş olamaz.\"\n  }\n}\nresource \"local_file\" \"not\" {\n  content  = var.icerik\n  filename = var.dosya_adi\n}\noutput \"yol\" { value = local_file.not.filename }\n\nmain.tf\nmodule \"a\" {\n  source    = \"./modules/not\"\n  dosya_adi = \"a.txt\"\n}\nmodule \"b\" {\n  source    = \"./modules/not\"\n  dosya_adi = \"b.txt\"\n  icerik    = \"ikinci\"\n}\noutput \"yollar\" { value = [module.a.yol, module.b.yol] }\n\nterraform init\nterraform plan\nterraform apply\nterraform state list\nterraform state show module.a.local_file.not\na.txt dosyasını elle değiştir, sonra terraform plan     (drift: plan farkı gösterir)\nTF_LOG=DEBUG terraform plan     (ayrıntılı günlük)\nterraform destroy\n\nBackend (yerel, kilitli): terraform { backend \"local\" { path = \"durum/terraform.tfstate\" } }  sonra terraform init -migrate-state\nImport ve uzak backend kâğıt üzerinde (simülasyon): import {\n  to = KAYNAK_ADRESI\n  id = \"MEVCUT_KAYNAK_KIMLIGI\"\n} ve S3 backend'de use_lockfile = true.","f":[["Hassas değeri yalnız sensitive = true yapıp güvende saymak","State dosyasında düz metin kalır; state'i şifreli ve erişimi kısıtlı uzak backend'de tut."],["Modül sürümünü sabitlemeden registry'den çekmek","Aynı kod farklı zamanda farklı modül getirebilir; version ile sabitle."]],"u":[["Birden çok kişi aynı state üzerinde çalışırken eşzamanlı apply'ı ne engeller?","State kilidi","terraform fmt","output bloğu"],["Elle değiştirilen bir kaynak ile state arasındaki farka ne denir?","Drift (sapma)","Rollback","Idempotency"],["Bulutta zaten var olan bir kaynağı Terraform yönetimine almak için ne kullanılır?","import (import bloğu ya da terraform import)","terraform fmt","terraform validate"],["sensitive = true olan değer state dosyasında nasıl durur?","Düz metin olarak yazılır; yalnız çıktıda gizlenir","Şifrelenir","Hiç yazılmaz"]],"p":["Değişken, çıktı ve modülle yeniden kullanılabilir yapı kuracaksın","State kilidi, uzak backend ve drift ilişkisini anlatacaksın","import, state komutları ve TF_LOG ile bakım yapacaksın"],"o":"Sonunda değişken ve modül kullanan bir Terraform projesini çalıştırabilecek, state'i yönetebilecek ve drift'i plan çıktısından okuyabileceksin.","n":["Terraform ileri: değişken, modül, durum ve HCP Terraform"]},{"k":"Monolitten mikroservise","h":"Uygulaman büyüdü ve her küçük değişiklik tüm sistemi yeniden dağıtmayı gerektiriyor. Parçalara bölmek her sorunu çözer mi?","m":[["Monolit","Tüm işlevlerin tek paket olarak derlenip tek birim olarak dağıtıldığı uygulama; süreç içi çağrılar hızlıdır, ama ölçekleme ve dağıtım hep topluca olur"],["Mikroservis","Her biri tek bir iş yeteneğine odaklanan, kendi verisine sahip, bağımsız dağıtılıp ölçeklenebilen küçük servisler; birbirleriyle ağ üzerinden API ile konuşur"],["Servis başına veri","Her servis kendi veritabanını yönetir; başka servis o veriye yalnız servisin API'si üzerinden ulaşır, böylece servisler gizli biçimde birbirine bağlanmaz"],["Boğucu incir (strangler fig)","Monoliti bir kerede yeniden yazmak yerine işlevleri tek tek yeni servislere taşıyıp eskisini yavaş yavaş küçültme yaklaşımı"]],"w":"Mikroservis bir hız hilesi değil, bir takas: bağımsız dağıtım ve ölçekleme kazanırsın, karşılığında ağ gecikmesi, dağıtık veri ve gözlem yükü ödersin. Konteyner ve Kubernetes bu takası yönetilebilir kılar.","x":"Kâğıt üzerinde bir alışveriş sitesi (simülasyon):\nMonolit:        [Katalog + Sepet + Ödeme + Kullanıcı]  -> tek paket, tek veritabanı\nMikroservis:    [Katalog] [Sepet] [Ödeme] [Kullanıcı]  -> her biri ayrı imaj, kendi veritabanı\n\nGüvenilirlik hesabı: 3 servis zincirleme çağrılıyor, her biri %99,9 ayakta.\nBirlikte: 0,999 x 0,999 x 0,999 = 0,997003 -> yaklaşık %99,70\nÇıkarım: zincir uzadıkça toplam erişilebilirlik düşer; zaman aşımı ve yeniden deneme bu yüzden gerekir.","f":[["Her şeyi mikroservis yapmak","Küçük ekip ve belirsiz alan için modüler monolit çoğu zaman daha ucuz ve hızlıdır; bölmeyi gerçek bir ölçek ya da ekip ihtiyacı doğurunca yap."],["Servislerin ortak veritabanını paylaşması","Ortak tablo servisleri gizlice birbirine bağlar ve bağımsız dağıtımı bozar; her servis kendi verisinin sahibi olmalı."]],"u":[["Tek paket halinde dağıtılan, tüm işlevleri bir arada olan uygulama mimarisine ne denir?","Monolit","Mikroservis","Sunucusuz (serverless)"],["Mikroservis mimarisinin başlıca kazancı hangisidir?","Servislerin bağımsız dağıtılıp ölçeklenebilmesi","Ağ çağrısının tamamen ortadan kalkması","Tek veritabanında tutarlılığın otomatik sağlanması"],["Monoliti riski azaltarak parça parça yeni servislere taşıma yaklaşımının adı nedir?","Boğucu incir (strangler fig)","Mavi-yeşil dağıtım","Kanarya yayını"]],"p":["Monolit ile mikroservisi karşılaştıracaksın","Mikroservisin maliyetlerini sayacaksın","Monoliti parçalamanın güvenli yolunu anlatacaksın"],"o":"Sonunda bir uygulamanın monolit mi mikroservis mi olması gerektiğini gerekçesiyle savunabilecek ve neden konteyner orkestrasyonuna ihtiyaç doğduğunu anlatabileceksin.","n":["Monolitten mikroservise"]},{"k":"API'ye giriş yolu: kimlik doğrulama, yetkilendirme ve admission control","h":"kubectl ile bir Pod oluşturmak istedin ve cevap '403 Forbidden' geldi. İsteğin API sunucusuna girerken hangi üç kapıdan geçtiğini bilirsen nedenini bulursun.","m":[["Kimlik doğrulama (authentication)","İsteği kimin gönderdiğini bulur: istemci sertifikası, taşıyıcı belirteç (ServiceAccount, OIDC) gibi yöntemlerden biri tutarsa kimlik belli olur; hiçbiri tutmazsa 401 döner"],["Yetkilendirme (authorization)","Kimliği belli isteğin bu işi yapmaya hakkı var mı sorusu: Node, ABAC, RBAC, Webhook kipleri; reddedilirse 403 döner"],["Admission control","Yetkilendirmeyi geçen oluşturma, değiştirme ve silme isteklerini nesne kalıcı yazılmadan önce değiştirebilen (mutating) ya da doğrulayan (validating) denetim; ResourceQuota, LimitRanger, PodSecurity bunun örnekleridir"],["Anonim istek","Kimlik bilgisi taşımayan istek; varsayılan olarak kabul edilir ve system:anonymous kullanıcısı sayılır, ama RBAC yetki vermediği sürece reddedilir"]],"w":"API sunucusu kümenin tek kapısıdır. İstek sırayla kimlik doğrulama, yetkilendirme ve admission control aşamalarından geçer; üçünü de geçen nesne etcd'ye yazılır. Hata kodu hangi kapıda takıldığını söyler.","x":"Yerel kümede (kind ya da minikube) gözlem:\nkubectl auth can-i create pods --as=system:anonymous      (anonim kullanıcı yetkisi: no)\nkubectl auth can-i create pods                            (kendi yetkin: yes)\nkubectl create namespace deneme\nkubectl create quota kucuk --hard=pods=2 -n deneme\nkubectl create deployment web --image=nginx --replicas=3 -n deneme\nkubectl get deploy,rs,pods -n deneme       (Deployment kabul edildi, 3 Pod'dan yalnız 2'si oluşur)\nkubectl describe rs -n deneme              (olaylarda 'exceeded quota' satırı)\nkubectl delete namespace deneme\n\nSıra:  İstek -> Kimlik doğrulama -> Yetkilendirme -> Admission (mutating, sonra validating) -> etcd","f":[["Admission control'ün okuma isteklerini de denetlediğini sanmak","Admission yalnız oluşturma, değiştirme, silme ve proxy bağlantı isteklerini yakalar; get, list, watch okumalarını engellemez."],["ResourceQuota'yı yetkilendirme aşaması sanmak","Kota admission control aşamasında uygulanır; yetkilendirmeyi geçen istek kota aşımında yine reddedilebilir."]],"u":[["API sunucusuna gelen bir istek hangi sırayla denetlenir?","Kimlik doğrulama, yetkilendirme, admission control","Admission control, kimlik doğrulama, yetkilendirme","Yetkilendirme, admission control, kimlik doğrulama"],["Kota denetimi API isteğinin hangi aşamasında yapılır?","Admission control","Kimlik doğrulama","Yalnız kubelet düzeyinde"],["Hangisi Kubernetes'te yetkilendirme kipi olarak kullanılamaz?","Pod","RBAC","Node"],["Kimlik doğrulaması yapılamayan bir isteğe hangi HTTP durum kodu döner?","401 Unauthorized","403 Forbidden","404 Not Found"]],"p":["Üç kapının sırasını sayacaksın","Hata kodundan takılan kapıyı bulacaksın","Admission control örneklerini ayırt edeceksin"],"o":"Sonunda bir isteğin API sunucusunda hangi sırayla denetlendiğini, hangi kapıda neden reddedilebileceğini ve ResourceQuota'nın nerede devreye girdiğini anlatabileceksin.","n":["API'ye giriş yolu: kimlik doğrulama, yetkilendirme ve admission control"]},{"k":"Service türleri karşılaştırma: ClusterIP, NodePort, LoadBalancer, ExternalName","h":"Pod'ların IP adresi her yeniden oluşumda değişir. Uygulamanı hem küme içinden hem dışarıdan nasıl sabit bir adresle erişilebilir yaparsın?","m":[["ClusterIP","Varsayılan tür; Service'e yalnız küme içinden erişilen sanal bir IP verir"],["NodePort","Her düğümde aynı sabit portu (varsayılan 30000-32767) açar ve trafiği Service'e yönlendirir; ClusterIP'yi de içerir"],["LoadBalancer","Bulut sağlayıcıdan bir dış yük dengeleyici ister; NodePort ve ClusterIP üzerine kurulur"],["ExternalName","Seçici ve proxy yoktur; Service adını DNS CNAME kaydıyla dış bir alan adına çevirir"]],"w":"Service, değişen Pod IP'lerinin önüne sabit bir ad ve adres koyar. Tür, bu adrese nereden erişileceğini belirler: yalnız içeriden, düğüm portundan, bulut yük dengeleyiciden ya da dış bir ada yönlendirmeyle.","x":"Yerel kümede (kind ya da minikube):\nkubectl create deployment web --image=nginx --replicas=2\nkubectl expose deployment web --port=80 --type=ClusterIP --name=web-ic\nkubectl expose deployment web --port=80 --type=NodePort --name=web-np\nkubectl get svc            (web-np PORT(S) sütununda 80:3xxxx/TCP görünür)\nkubectl get endpointslices (Service'in arkasındaki Pod IP'leri)\nminikube service web-np --url     (minikube'da dışarıdan adres)\nkubectl delete svc web-ic web-np; kubectl delete deployment web\n\nKarşılaştırma (kâğıt üzerinde):\nTür           Erişim                 Ek kaynak\nClusterIP     yalnız küme içi        yok\nNodePort      düğümIP:nodePort       ClusterIP dahil\nLoadBalancer  bulut dış IP          NodePort + ClusterIP dahil\nExternalName  DNS CNAME             IP ve proxy yok","f":[["NodePort'u üretimde birincil dış erişim sanmak","Düğüm IP'sine ve sabit porta bağlıdır; üretimde genellikle LoadBalancer ya da Ingress kullanılır."],["ExternalName'in trafiği proxy'lediğini sanmak","Yalnız DNS CNAME döner; trafik doğrudan istemciden hedefe gider."]],"u":[["Service türü belirtilmezse varsayılan hangisidir?","ClusterIP","NodePort","LoadBalancer"],["NodePort için varsayılan port aralığı hangisidir?","30000-32767","1-1023","8000-9000"],["Hangi Service türü DNS CNAME kaydıyla bir dış alan adına yönlendirir?","ExternalName","ClusterIP","NodePort"],["Bulut sağlayıcıdan dış bir yük dengeleyici isteyen tür hangisidir?","LoadBalancer","ClusterIP","ExternalName"]],"p":["Dört Service türünü ayıracaksın","Türlerin birbiri üzerine kurulduğunu anlatacaksın","Senaryoya uygun türü seçeceksin"],"o":"Sonunda bir erişim ihtiyacı için doğru Service türünü seçip nedenini söyleyebilecek ve her türün hangi kaynakları içerdiğini sayabileceksin.","n":["Service türleri karşılaştırma: ClusterIP, NodePort, LoadBalancer, ExternalName"]},{"k":"kube-proxy, ReplicaSet ve mikroservislerin Kubernetes'te çalışması","h":"Bir Service'e istek attığında paket hangi Pod'a gideceğini nasıl biliyor ve bir Pod silinince yerine kim yenisini açıyor?","m":[["kube-proxy","Her düğümde çalışır; API sunucusundan Service ve EndpointSlice değişikliklerini izler ve düğümde trafiği Pod'lara yönlendiren kuralları (iptables, IPVS ya da nftables) kurar"],["ReplicaSet","Etiket seçicisine uyan Pod sayısını istenen sayıda tutan denetleyici; eksik Pod'u açar, fazlasını siler"],["Deployment ve ReplicaSet","Deployment sürüm geçişini ReplicaSet'ler üzerinden yürütür; her sürüm için ayrı ReplicaSet oluşur"],["Servis başına Deployment","Mikroserviste her servis genellikle bir Deployment ve bir Service çiftiyle çalışır; servisler birbirini DNS adıyla bulur"]],"w":"Service sanal bir adrestir; gerçek yönlendirmeyi her düğümdeki kube-proxy kuralları yapar. Pod sayısını ise ReplicaSet sabit tutar, bu yüzden Pod'u elle silmek kalıcı çözüm olmaz.","x":"Yerel kümede:\nkubectl create deployment web --image=nginx --replicas=3\nkubectl get rs                         (web-xxxx  DESIRED 3  CURRENT 3  READY 3)\nkubectl delete pod -l app=web --wait=false   (üçünü sil)\nkubectl get pods                       (ReplicaSet yenilerini açar)\nkubectl scale deployment web --replicas=5\nkubectl get rs\nkubectl set image deployment/web nginx=nginx:1.27    (yeni ReplicaSet, eskisi 0'a iner)\nkubectl get rs\nkubectl delete deployment web\n\nRolling update hesabı: replicas=10, maxSurge=%25, maxUnavailable=%25\nmaxSurge yukarı yuvarlanır: 3, maxUnavailable aşağı yuvarlanır: 2\nGeçişte en çok 13 Pod, en az 8 hazır Pod.","f":[["Pod'u elle silip sorunu çözdüğünü sanmak","ReplicaSet yenisini açar; kalıcı değişiklik için Deployment'ı düzenle."],["ReplicaSet'i doğrudan kullanıp sürüm geçişi beklemek","Rolling update ve geri alma Deployment'ın işidir; ReplicaSet yalnız kopya sayısını tutar."]],"u":[["kube-proxy hangi düğümlerde çalışır?","Her düğümde","Yalnız kontrol düzlemi düğümünde","Yalnız master olmayan tek düğümde"],["ReplicaSet'in temel görevi nedir?","İstenen sayıda Pod'u çalışır halde tutmak","İmajları derlemek","Düğümleri kurmak"],["Rolling update sırasında maxSurge neyi belirler?","İstenen sayının üstüne çıkılabilecek ek Pod sayısını","En fazla kaç Pod'un silinebileceğini","Düğüm sayısını"],["Deployment sürüm güncellerken eski Pod'ları ne yönetir?","Eski ve yeni ReplicaSet'ler","kube-proxy","etcd"]],"p":["kube-proxy'nin görevini anlatacaksın","ReplicaSet ile Deployment ilişkisini ayıracaksın","Rolling update sayılarını hesaplayacaksın"],"o":"Sonunda bir Service trafiğinin Pod'a nasıl ulaştığını, Pod silinince ne olduğunu ve rolling update'te Pod sayılarının nasıl hesaplandığını anlatabileceksin.","n":["kube-proxy, ReplicaSet ve mikroservislerin Kubernetes'te çalışması"]},{"k":"kubectl ile Pod çalıştırınca ne olur: istekten konteynere akış","h":"kubectl run web --image=nginx yazıp Enter'a bastın. Saniyeler içinde Pod çalıştı; arka planda hangi bileşenler hangi sırayla ne yaptı?","m":[["API sunucusu","Tüm isteklerin girdiği tek kapı; kimlik, yetki ve admission denetimlerinden sonra nesneyi etcd'ye yazan tek bileşendir"],["Scheduler","nodeName'i boş Pod'ları izler; düğümleri eler (filter) ve puanlar (score), seçtiği düğümü Pod'a bağlar (bind)"],["Kubelet","Düğümde kendisine atanan Pod'ları izler; container runtime'a CRI üzerinden konteyner başlattırır ve durumu API sunucusuna bildirir"],["Controller manager","Deployment gibi üst nesneler için ReplicaSet ve Pod oluşturan denetim döngülerini çalıştırır; çıplak Pod için gerekmez"]],"w":"Bileşenler birbirine doğrudan komut vermez; hepsi API sunucusundaki nesneyi izler ve kendi payına düşeni yapar. Pod önce 'atanmamış' olarak etcd'ye yazılır, scheduler düğümü seçer, kubelet çalıştırır.","x":"Yerel kümede izleme:\nkubectl get pod web -w                       (başka terminalde)\nkubectl run web --image=nginx\nkubectl get pod web -o wide                 (NODE sütunu: scheduler'ın seçimi)\nkubectl describe pod web                    (Events: Scheduled, Pulling, Pulled, Created, Started)\nkubectl get events --sort-by=.metadata.creationTimestamp\nkubectl delete pod web\n\nAkış:\nkubectl -> API sunucusu (kimlik, yetki, admission) -> etcd (Pending, nodeName boş)\n  -> scheduler (düğüm seçer ve bağlar) -> API sunucusu -> etcd\n  -> kubelet (CRI ile runtime) -> imaj çek, konteyner başlat -> durum Running -> etcd\n\nSayım: kubectl create deployment web --replicas=3 -> 1 Deployment + 1 ReplicaSet + 3 Pod = 5 nesne.","f":[["Scheduler'ın Pod'u çalıştırdığını sanmak","Scheduler yalnız düğümü seçer; konteyneri düğümdeki kubelet ve runtime başlatır."],["Bileşenlerin etcd ile doğrudan konuştuğunu sanmak","Yalnız API sunucusu etcd'ye yazar ve okur; diğerleri API sunucusu üzerinden çalışır."]],"u":[["Hangi bileşen kümede nesneleri etcd'ye yazan tek bileşendir?","API sunucusu","Scheduler","Kubelet"],["Pod'un hangi düğümde çalışacağına kim karar verir?","Scheduler","Kubelet","kube-proxy"],["Konteyneri düğümde fiilen başlatılmasını kim tetikler?","Kubelet, container runtime aracılığıyla","Scheduler","etcd"],["kubectl create deployment web --replicas=3 kaç Pod oluşturur?","3 Pod (ayrıca 1 Deployment ve 1 ReplicaSet nesnesi)","1 Pod","6 Pod"]],"p":["İstek akışını sırayla sayacaksın","Her bileşenin tek görevini ayıracaksın","Olaylardan akışı okuyacaksın"],"o":"Sonunda kubectl run komutundan konteyner çalışana kadar hangi bileşenin ne yaptığını sırayla anlatabilecek ve kubectl describe olaylarından akışı okuyabileceksin.","n":["kubectl ile Pod çalıştırınca ne olur: istekten konteynere akış"]},{"k":"Kubernetes'i genişletmek: CRI, RuntimeClass, CRD ve Operator","h":"Kubernetes'in kendi tanımadığı bir 'Veritabanı' nesnesini yönetmesini ve bazı Pod'ların farklı, daha izole bir runtime ile çalışmasını nasıl sağlarsın?","m":[["CRI ve runtime","Container Runtime Interface kubelet ile container runtime arasındaki arayüzdür; containerd ve CRI-O CRI uygulayan yaygın runtime'lardır, Docker Engine'e doğrudan destek (dockershim) 1.24'te kaldırıldı"],["RuntimeClass","Pod'un hangi runtime yapılandırmasıyla (örneğin runc, gVisor, Kata) çalışacağını runtimeClassName ile seçtiren küme nesnesi"],["CRD","CustomResourceDefinition ile API'ye yeni bir kaynak türü eklemek; kaynaklar kubectl ile yönetilir ve etcd'de saklanır, şema doğrulaması yapılabilir"],["Operator","Bir CRD ve onu izleyip gerçek durumu istenen duruma getiren özel denetleyiciden oluşan, bir uygulamanın işletme bilgisini kodlayan desen"]],"w":"Kubernetes genişletilebilir tasarlanmıştır: runtime, ağ ve depolama standart arayüzlerle takılır, API ise CRD ile yeni nesnelerle büyür. Operator bu genişlemeye 'işi bilen' bir denetleyici ekler.","x":"Kâğıt üzerinde (simülasyon) bir CRD ve bir kaynak:\napiVersion: apiextensions.k8s.io/v1\nkind: CustomResourceDefinition\nmetadata:\n  name: yedekler.ornek.dev\nspec:\n  group: ornek.dev\n  scope: Namespaced\n  names: { plural: yedekler, singular: yedek, kind: Yedek }\n  versions: [ { name: v1, served: true, storage: true } ]\n\nYerel kümede (kind ya da minikube) yalnız izleme:\nkubectl get crd                       (kümedeki CRD'ler)\nkubectl api-resources | head          (yerleşik ve özel kaynaklar)\nkubectl get runtimeclass              (küme tanımlıysa; yoksa 'No resources found')\n\nRuntimeClass'ı Pod'da seçmek:\nspec:\n  runtimeClassName: gvisor","f":[["Docker kaldırıldı diye Docker imajlarının çalışmayacağını sanmak","İmajlar OCI standardındadır; containerd ve CRI-O aynı imajı çalıştırır, kaldırılan dockershim köprüsüdür."],["CRD'yi tek başına davranış sanmak","CRD yalnız yeni kaynak türünü tanımlar; o kaynağa göre iş yapan bir denetleyici (Operator) ayrıca gerekir."]],"u":[["kubelet ile container runtime arasındaki standart arayüzün adı nedir?","CRI (Container Runtime Interface)","CNI","CSI"],["Pod'un hangi runtime yapılandırmasını kullanacağını seçmeye ne yarar?","RuntimeClass","Namespace","ConfigMap"],["API'ye yeni bir kaynak türü eklemek için ne kullanılır?","CustomResourceDefinition (CRD)","Deployment","Ingress"],["Bir CRD ve özel denetleyiciden oluşan, uygulamanın işletme bilgisini kodlayan desene ne denir?","Operator","DaemonSet","Sidecar"]],"p":["CRI, CNI ve CSI'yi ayıracaksın","RuntimeClass ve CRD'nin işlevini anlatacaksın","Operator desenini tanımlayacaksın"],"o":"Sonunda containerd/CRI-O'nun rolünü, RuntimeClass, CRD ve Operator'ın ne işe yaradığını ve birbirinden farkını anlatabileceksin.","n":["Kubernetes'i genişletmek: CRI, RuntimeClass, CRD ve Operator"]},{"k":"RBAC ve Pod Security Standards ile küme güvenliği","h":"Bir CI hesabının yalnız bir ad alanında Pod okumasını istiyorsun, ve hiçbir Pod'un ayrıcalıklı (privileged) çalışmamasını. İkisini hangi mekanizmalarla sağlarsın?","m":[["Role ve ClusterRole","Role bir ad alanındaki izinleri, ClusterRole tüm kümedeki ya da ad alanından bağımsız kaynaklardaki izinleri tanımlar; yalnız izin ekler, yasaklama kuralı yoktur"],["RoleBinding ve ClusterRoleBinding","İzinleri kullanıcı, grup ya da ServiceAccount'a bağlar; RoleBinding ad alanı kapsamlıdır, ClusterRoleBinding küme geneli"],["Pod Security Standards","Üç güvenlik profili: Privileged (kısıtsız), Baseline (bilinen yetki yükseltmelerini engeller), Restricted (sıkılaştırılmış en iyi uygulamalar)"],["Pod Security Admission","Profilleri ad alanı etiketleriyle (enforce, audit, warn) uygulayan yerleşik admission denetleyicisi"]],"w":"RBAC 'kim ne yapabilir' sorusunu, Pod Security Standards 'Pod ne yapabilir' sorusunu yanıtlar. İkisi birlikte en az ayrıcalık ilkesini uygular: önce hiçbir şeye izin yok, sonra gerekeni ver.","x":"Yerel kümede (kind ya da minikube):\nkubectl create namespace dev\nkubectl create role pod-okuyucu --verb=get,list,watch --resource=pods -n dev\nkubectl create serviceaccount ci -n dev\nkubectl create rolebinding ci-okur --role=pod-okuyucu --serviceaccount=dev:ci -n dev\nkubectl auth can-i list pods -n dev --as=system:serviceaccount:dev:ci      (yes)\nkubectl auth can-i delete pods -n dev --as=system:serviceaccount:dev:ci    (no)\nkubectl auth can-i list pods -n default --as=system:serviceaccount:dev:ci   (no)\n\nPod Security Admission:\nkubectl label namespace dev pod-security.kubernetes.io/enforce=baseline\nkubectl run kotu --image=nginx -n dev --overrides='{\"spec\":{\"containers\":[{\"name\":\"kotu\",\"image\":\"nginx\",\"securityContext\":{\"privileged\":true}}]}}'\n(ayrıcalıklı Pod, baseline profilinde admission'da reddedilir)\nkubectl delete namespace dev","f":[["RBAC'ta 'yasakla' kuralı aramak","RBAC yalnız izin verir; verilmeyen şey yasaktır. Yasaklamak için izni hiç vermezsin."],["cluster-admin'i kolaylık için herkese vermek","En az ayrıcalık ilkesine aykırıdır; gereken fiil ve kaynak kadar izin ver."]],"u":[["RBAC'ta izinleri bir ad alanı içinde tanımlayan nesne hangisidir?","Role","ClusterRoleBinding","NetworkPolicy"],["Pod Security Standards'ın üç profili hangileridir?","Privileged, Baseline, Restricted","Low, Medium, High","Dev, Test, Prod"],["Pod Security Admission profilleri hangi yolla uygular?","Ad alanı etiketleriyle (enforce, audit, warn)","Her Pod'a elle sertifika vererek","kube-proxy kuralıyla"],["RBAC'ta açıkça yasaklayan (deny) bir kural yazılabilir mi?","Hayır; RBAC yalnız izin ekler","Evet, Role içinde deny alanıyla","Evet, ancak yalnız ClusterRole ile"]],"p":["Role/Binding ilişkisini kuracaksın","Üç Pod güvenlik profilini ayıracaksın","can-i ile yetkiyi doğrulayacaksın"],"o":"Sonunda bir ServiceAccount'a ad alanı kapsamlı okuma izni verebilecek, kubectl auth can-i ile doğrulayabilecek ve Pod Security profillerini ad alanına uygulayabileceksin.","n":["RBAC ve Pod Security Standards ile küme güvenliği"]},{"k":"Gözlemlenebilirlik yığını ve CNCF topluluğu: Prometheus, OpenTelemetry, SIG ve KEP","h":"Sistem yavaşladı. Hangi servis yavaş, ne zamandır, ve hangi istek yolunda takıldı? Cevabı metrik, log ve izlerle (trace) ararsın.","m":[["Üç sütun","Metrikler sayısal zaman serileridir, loglar olay kayıtlarıdır, izler (traces) bir isteğin servisler arasındaki yolunu ve sürelerini gösterir"],["Prometheus","Hedeflerin /metrics uç noktalarını belirli aralıkla çeken (pull) zaman serisi izleme sistemi; sorgu dili PromQL, uyarıları Alertmanager yönetir"],["OpenTelemetry","Metrik, log ve iz üretimi için tedarikçiden bağımsız API, SDK ve toplayıcı (collector) sağlayan CNCF projesi"],["SIG ve KEP","Kubernetes geliştirmesi konu bazlı Özel İlgi Grupları (SIG) ile yürür; yeni özellikler Kubernetes Enhancement Proposal (KEP) ile önerilir"]],"w":"Gözlemlenebilirlik, sistemin dışarıdan görülen çıktılarından iç durumunu anlayabilmektir. Kubernetes'te metrik için Prometheus, log için toplayıcılar, iz için OpenTelemetry ve Jaeger gibi araçlar birlikte kullanılır.","x":"Yerel kümede (kind ya da minikube):\nkubectl logs deploy/web --tail=20          (konteyner çıktısı)\nkubectl top pods                            (metrics-server kuruluysa CPU ve bellek)\nkubectl get --raw /metrics | head           (API sunucusunun Prometheus biçimindeki metrikleri; yetkin varsa)\n\nPromQL hesabı (kâğıt üzerinde):\nSayaç http_istek_toplam: t=0 sn'de 1200, t=60 sn'de 1800\nrate(...[1m]) = (1800 - 1200) / 60 = 10 istek/sn\n\nHata bütçesi: SLO %99,9, 30 günlük pencere\n30 x 24 x 60 = 43200 dk; hata bütçesi = 43200 x 0,001 = 43,2 dk","f":[["Prometheus'un hedeflere veri ittiğini sanmak","Prometheus varsayılan olarak çeker (pull); kısa ömürlü işler için ayrı bir ara katman gerekir."],["Loglarla metriği aynı şey sanmak","Log tek olayın kaydıdır, metrik sayısal bir ölçümün zamana göre serisidir; ikisi farklı sorulara yanıt verir."]],"u":[["Bir sistemi dışarıdan anlamak için toplanan üç sinyal türü hangisidir?","Metrik, log, iz (trace)","CPU, disk, ağ","Pod, Service, Ingress"],["Prometheus metrikleri nasıl toplar?","Hedeflerin /metrics uç noktasını periyodik olarak çeker (pull)","Hedeflerden gelen veriyi dinler (push)","Yalnız logları ayrıştırarak"],["Tedarikçiden bağımsız iz ve metrik toplama standardı sağlayan CNCF projesi hangisidir?","OpenTelemetry","Helm","etcd"],["Kubernetes'e yeni özellik önermenin standart belgesi nedir?","KEP (Kubernetes Enhancement Proposal)","RFC 2616","Dockerfile"]],"p":["Üç sinyali ayıracaksın","Prometheus modelini anlatacaksın","CNCF yapısını ve KCNA alanlarını sayacaksın"],"o":"Sonunda metrik, log ve iz farkını anlatabilecek, bir sayaç için rate hesaplayabilecek ve SIG, KEP, CNCF olgunluk aşamalarını sayabileceksin.","n":["Gözlemlenebilirlik yığını ve CNCF topluluğu: Prometheus, OpenTelemetry, SIG ve KEP"]}];
